import { experimental_createHostEntryHarness } from "@get-bb/plugin-sdk/testing/host";
import { describe, expect, it } from "vitest";
import { javascriptFixture } from "./test/debugger-client.js";

describe("built plugin artifacts", () => {
  it("loads the bundled host and starts the JavaScript DevTools debugger dependency", async () => {
    // @ts-expect-error dist is generated by the pretest build
    const builtHostModule = await import("./dist/host.js");

    const harness = experimental_createHostEntryHarness(builtHostModule.default);
    const target = {
      threadId: "bundled-thread",
      workspacePath: process.cwd(),
      enginePath: null,
    } as const;
    const call = async <T>(tool: string, argumentsValue: Record<string, unknown>) => {
      const response = (await harness.experimental_call("callTool", {
        ...target,
        tool,
        arguments: argumentsValue,
      })) as { content: Array<{ type: string; text?: string }> };
      const text = response.content.find((part) => part.type === "text")?.text;
      if (text === undefined) throw new Error(`${tool} did not return JSON text`);
      return JSON.parse(text) as T;
    };
    let sessionId: string | undefined;
    try {
      const result = (await harness.experimental_call("doctor", target)) as {
        tools: string[];
      };
      expect(result.tools).toContain("create_debug_session");
      const created = await call<{
        sessionId?: string;
        error?: string;
        message?: string;
      }>("create_debug_session", { language: "javascript" });
      if (created.sessionId === undefined) {
        throw new Error(created.error ?? created.message ?? JSON.stringify(created));
      }
      sessionId = created.sessionId;
      await call("set_breakpoint", {
        sessionId,
        file: javascriptFixture,
        statement: "state.count += index;",
      });
      const started = await call<{ state?: string; error?: string }>(
        "start_debugging",
        { sessionId, scriptPath: javascriptFixture },
      );
      const stopped = await call<{
        state?: string;
        error?: string;
        message?: string;
      }>("wait_for_stop", { sessionId, timeout: 20_000 });
      if (stopped.state !== "paused") {
        throw new Error(JSON.stringify({ started, stopped }));
      }
      const locals = await call<{
        variables: Array<{ name: string; value: string }>;
      }>("get_local_variables", { sessionId, names: ["index"] });
      expect(locals.variables).toContainEqual(
        expect.objectContaining({ name: "index", value: "0" }),
      );
    } finally {
      if (sessionId !== undefined) {
        await call("close_debug_session", { sessionId }).catch(() => undefined);
      }
      await harness.experimental_dispose();
    }
  }, 45_000);
});
